type HierarchyRule struct {
	// IncludeLevel defines how many parents or ancestors to traverse
	// upwards in a containment hierarchy to find candidate nodes.
	IncludeLevel int `json:"includeLevel"`

	// ExcludeLevel defines how many parents or ancestors to traverse
	// upwards in a containment hierarchy to find an exclusion set of
	// nodes.
	ExcludeLevel int `json:"excludeLevel"`
}

blance.includeExclude.code:
func includeExcludeNodes(node string,
	includeLevel int,
	excludeLevel int,
	mapParents map[string]string,
	mapChildren map[string][]string) []string {
	incNodes :=
		findLeaves(findAncestor(node, mapParents, includeLevel), mapChildren)
	excNodes :=
		findLeaves(findAncestor(node, mapParents, excludeLevel), mapChildren)

	return StringsRemoveStrings(incNodes, excNodes)
}

